package employee.management.system;import javax.swing.*;import java.awt.*;public class Splash extends JFrame {    Splash() {        setTitle("Employee Management System");        setSize(800, 450);        setLocation(350, 200);        setUndecorated(true);        JPanel backgroundPanel = new JPanel() {            @Override            protected void paintComponent(Graphics g) {                super.paintComponent(g);                Graphics2D g2d = (Graphics2D) g;                Color color1 = new Color(20, 20, 20);                Color color2 = new Color(60, 60, 60);                GradientPaint gp = new GradientPaint(0, 0, color1, 0, getHeight(), color2);                g2d.setPaint(gp);                g2d.fillRect(0, 0, getWidth(), getHeight());            }        };        backgroundPanel.setLayout(null);        setContentPane(backgroundPanel);        JLabel heading = new JLabel("EMPLOYEE MANAGEMENT SYSTEM", SwingConstants.CENTER);        heading.setFont(new Font("Segoe UI", Font.BOLD, 30));        heading.setForeground(Color.WHITE);        heading.setBounds(50, 150, 700, 50);        backgroundPanel.add(heading);        JLabel tagline = new JLabel("Simplifying Workforce Management", SwingConstants.CENTER);        tagline.setFont(new Font("Segoe UI", Font.PLAIN, 18));        tagline.setForeground(new Color(200, 200, 200));        tagline.setBounds(50, 200, 700, 30);        backgroundPanel.add(tagline);        JLabel loading = new JLabel("Loading...", SwingConstants.CENTER);        loading.setFont(new Font("Segoe UI", Font.PLAIN, 14));        loading.setForeground(new Color(180, 180, 180));        loading.setBounds(50, 300, 700, 30);        backgroundPanel.add(loading);        setVisible(true);        try {            for (int i = 0; i <= 100; i += 5) {                Thread.sleep(150);                loading.setText("Loading " + i + "%...");            }            setVisible(false);            new Login();        } catch (Exception e) {            e.printStackTrace();        }    }    public static void main(String[] args) {        new Splash();    }}